<?php
declare(strict_types=1);
require_once __DIR__ . '/bbs_list_query.php';

require_once __DIR__.'/../lib/bbs_community.php';
require_once __DIR__.'/bbs_smart_card.php';

function bbs_comm_admin(array $user): bool { return strcasecmp((string)($user['role']??''),'Admin')===0; }
function bbs_comm_employee(array $user,?PDO $pdo=null): ?array { $pdo=$pdo?:db();$stmt=$pdo->prepare("SELECT e.EmployeeID,e.EmployeeName,e.Department,e.Unit,e.Position,e.Role,d.id DepartmentID,u.id SafetyUnitID FROM employees e LEFT JOIN master_departments d ON LOWER(TRIM(d.Name))=LOWER(TRIM(e.Department)) LEFT JOIN master_safetyunits u ON u.department_id=d.id AND LOWER(TRIM(u.name))=LOWER(TRIM(e.Unit)) WHERE e.EmployeeID=? LIMIT 1");$stmt->execute([(string)$user['id']]);$row=$stmt->fetch();return$row?:null; }
function bbs_comm_enabled(string $key): bool { $row=db_row('SELECT SettingValue FROM BBS_Settings WHERE SettingKey=? LIMIT 1',[$key]);return(string)($row['SettingValue']??'0')==='1'; }
function bbs_comm_template_dir(): string { $dir=dirname(__DIR__,2).'/backend/private-uploads/bbs-card-templates';if(!is_dir($dir))mkdir($dir,0770,true);return$dir; }
function bbs_comm_report_dir(): string { $dir=dirname(__DIR__,2).'/backend/private-uploads/bbs-community';if(!is_dir($dir))mkdir($dir,0770,true);return$dir; }
function bbs_comm_active_qr(int $departmentId,?PDO $pdo=null): ?array { $pdo=$pdo?:db();$stmt=$pdo->prepare("SELECT q.*,d.Name DepartmentName FROM BBS_Department_QR_Cards q JOIN master_departments d ON d.id=q.DepartmentID WHERE q.DepartmentID=? AND q.Status='Active' LIMIT 1");$stmt->execute([$departmentId]);$row=$stmt->fetch();return$row?:null; }
function bbs_comm_qr_payload(array $row): array { $raw=bbs_community_raw_token((int)$row['DepartmentID'],(int)$row['Generation']);return array_merge($row,['rawToken'=>$raw,'qrUrl'=>bbs_card_app_url().'#bbs-qr='.$raw]); }
function bbs_comm_upload(string $field,string $dir,bool $required=false): ?array { $file=$_FILES[$field]??null;if(!is_array($file)||(int)($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE){if($required)json_response(['success'=>false,'message'=>'A JPG, PNG, or WebP image is required.'],400);return null;}if((int)($file['error']??0)!==UPLOAD_ERR_OK)json_response(['success'=>false,'message'=>'Image upload failed.'],400);if((int)($file['size']??0)>10*1024*1024)json_response(['success'=>false,'message'=>'Image must not exceed 10 MB.'],400);$mime=bbs_card_file_mime((string)$file['tmp_name']);if(!in_array($mime,['image/jpeg','image/png','image/webp'],true))json_response(['success'=>false,'message'=>'Image content must be JPEG, PNG, or WebP.'],400);$ext=['image/jpeg'=>'.jpg','image/png'=>'.png','image/webp'=>'.webp'][$mime];$stored=time().'-'.bin2hex(random_bytes(18)).$ext;$target=$dir.'/'.basename($stored);if(!move_uploaded_file((string)$file['tmp_name'],$target))json_response(['success'=>false,'message'=>'Unable to store image.'],500);return['stored'=>$stored,'target'=>$target,'name'=>bbs_card_clean($file['name']??'image',255),'mime'=>$mime,'size'=>(int)$file['size']]; }
function bbs_comm_period(): array { $year=max(2000,min(2100,(int)($_GET['year']??date('Y'))));$month=(int)($_GET['month']??0);$sql='YEAR(r.CreatedAt)=?';$params=[$year];if($month>=1&&$month<=12){$sql.=' AND MONTH(r.CreatedAt)=?';$params[]=$month;}return[$year,$month,$sql,$params]; }

function handle_bbs_community_routes(string $method,string $path): bool {
    if(strpos($path,'/bbs/')!==0)return false;
    $user=require_user();$employee=bbs_comm_employee($user);$isAdmin=bbs_comm_admin($user);

    if($method==='GET'&&$path==='/bbs/department-cards/me'){
        if(!bbs_comm_enabled('department_cards_enabled'))json_response(['success'=>true,'data'=>['enabled'=>false,'department'=>null,'templates'=>[],'qr'=>null]]);
        $departmentId=$isAdmin&&isset($_GET['departmentId'])?bbs_phase1_positive_int($_GET['departmentId']):(int)($employee['DepartmentID']??0);if(!$departmentId)json_response(['success'=>false,'message'=>'Your Employee Master record is not linked to a Department.'],409);
        $department=db_row('SELECT id,Name FROM master_departments WHERE id=?',[$departmentId]);if(!$department)json_response(['success'=>false,'message'=>'Department was not found.'],404);$templates=db_rows("SELECT id,TemplateName,DepartmentID,OriginalName,MimeType,FileSize,WidthMM,HeightMM,DisplayOrder,Status FROM BBS_Department_Card_Templates WHERE DepartmentID=? AND Status='Active' ORDER BY DisplayOrder,TemplateName,id",[$departmentId]);$qr=bbs_comm_active_qr($departmentId);json_response(['success'=>true,'data'=>['enabled'=>true,'department'=>$department,'templates'=>$templates,'qr'=>$qr?bbs_comm_qr_payload($qr):null,'canReport'=>(bool)$qr]]);
    }
    $fileRoute=route_params($path,'/bbs/department-card-templates/:id/file');if($method==='GET'&&$fileRoute!==null){$row=db_row('SELECT * FROM BBS_Department_Card_Templates WHERE id=?',[bbs_phase1_positive_int($fileRoute['id'])]);if(!$row||(!$isAdmin&&$row['Status']!=='Active'))json_response(['success'=>false,'message'=>'Department card template was not found.'],404);if(!$isAdmin&&(int)$row['DepartmentID']!==(int)($employee['DepartmentID']??0))json_response(['success'=>false,'message'=>'This template belongs to another Department.'],403);$file=bbs_comm_template_dir().'/'.basename((string)$row['BackgroundStoredName']);if(!is_file($file))json_response(['success'=>false,'message'=>'Template file was not found.'],404);header('Content-Type: '.$row['MimeType']);header("Content-Disposition: inline; filename*=UTF-8''".rawurlencode((string)$row['OriginalName']));header('Cache-Control: private, no-store');readfile($file);exit;}
    if($method==='POST'&&$path==='/bbs/department-cards/print-log'){$body=json_body();$templateId=bbs_phase1_positive_int($body['templateId']??null);$copies=bbs_phase1_positive_int($body['copies']??null);$paper=bbs_community_paper_size($body['paperSize']??'');if(!$templateId||!$copies||$copies>100||!$paper)json_response(['success'=>false,'message'=>'Template, 1-100 copies, and A4/A5/A6 paper size are required.'],400);$template=db_row("SELECT * FROM BBS_Department_Card_Templates WHERE id=? AND Status='Active'",[$templateId]);if(!$template)json_response(['success'=>false,'message'=>'Active Department template was not found.'],404);if(!$isAdmin&&(int)$template['DepartmentID']!==(int)($employee['DepartmentID']??0))json_response(['success'=>false,'message'=>'You may print only your own Department templates.'],403);$qr=bbs_comm_active_qr((int)$template['DepartmentID']);if(!$qr)json_response(['success'=>false,'code'=>'DEPARTMENT_QR_REQUIRED','message'=>'This Department does not have an Active Community QR.'],409);$stmt=db()->prepare('INSERT INTO BBS_Department_Card_Print_Logs(TemplateID,DepartmentQRID,PaperSize,Copies,PrintedBy) VALUES(?,?,?,?,?)');$stmt->execute([$templateId,$qr['id'],$paper,$copies,$user['id']]);json_response(['success'=>true,'data'=>['id'=>(int)db()->lastInsertId(),'copies'=>$copies,'paperSize'=>$paper]],201);}
    if($method==='GET'&&$path==='/bbs/community/employees'){$departmentId=$isAdmin&&isset($_GET['departmentId'])?bbs_phase1_positive_int($_GET['departmentId']):(int)($employee['DepartmentID']??0);if(!$departmentId)json_response(['success'=>false,'message'=>'Department is unavailable.'],409);$rows=db_rows("SELECT e.EmployeeID,e.EmployeeName,e.Department,e.Unit,e.Position,u.id SafetyUnitID FROM employees e JOIN master_departments d ON d.id=? AND LOWER(TRIM(d.Name))=LOWER(TRIM(e.Department)) LEFT JOIN master_safetyunits u ON u.department_id=d.id AND LOWER(TRIM(u.name))=LOWER(TRIM(e.Unit)) ORDER BY e.EmployeeName LIMIT 1000",[$departmentId]);$units=db_rows('SELECT id,name FROM master_safetyunits WHERE department_id=? ORDER BY name',[$departmentId]);json_response(['success'=>true,'data'=>['departmentId'=>$departmentId,'rows'=>$rows,'units'=>$units]]);}
    if($method==='GET'&&$path==='/bbs/community/dashboard'){
        if(!bbs_comm_enabled('community_reporting_enabled'))json_response(['success'=>true,'data'=>['enabled'=>false,'good'=>[],'summary'=>['good'=>0]]]);
        [$year,$month,$period,$periodParams]=bbs_comm_period();$paging=bbs_list_query($_GET);$q=bbs_list_search($_GET['q']??'');$departmentId=bbs_phase1_positive_int($_GET['departmentId']??null);$unitId=bbs_phase1_positive_int($_GET['safetyUnitId']??null);$actionStatus=bbs_card_clean($_GET['actionStatus']??'',40);$priority=bbs_card_clean($_GET['priority']??'',20);$goodPage=max(1,(int)($_GET['goodPage']??$paging['page']));$riskPage=max(1,(int)($_GET['riskyPage']??$paging['page']));$filter=[$period];$filterParams=$periodParams;if($departmentId){$filter[]='r.DepartmentID=?';$filterParams[]=$departmentId;}if($unitId){$filter[]='r.SafetyUnitID=?';$filterParams[]=$unitId;}if($q!==''){$filter[]='(r.ReportNo LIKE ? OR r.AreaText LIKE ? OR r.Description LIKE ? OR d.Name LIKE ? OR u.name LIKE ? OR observed.EmployeeID LIKE ? OR observed.EmployeeName LIKE ?)';for($i=0;$i<7;$i++)$filterParams[]='%'.$q.'%';}$base=implode(' AND ',$filter);$joins='JOIN master_departments d ON d.id=r.DepartmentID LEFT JOIN master_safetyunits u ON u.id=r.SafetyUnitID LEFT JOIN employees observed ON observed.EmployeeID=r.ObservedEmployeeID';$goodWhere="r.ReportType='Good' AND $base";$goodSelect="SELECT r.id,r.ReportNo,r.DepartmentID,d.Name DepartmentName,r.SafetyUnitID,u.name SafetyUnitName,r.AreaText,r.Description,r.CreatedAt,observed.EmployeeID ObservedEmployeeID,observed.EmployeeName ObservedEmployeeName,(SELECT COUNT(*) FROM BBS_Community_Report_Files f WHERE f.ReportID=r.id) EvidenceCount FROM BBS_Community_Reports r $joins WHERE $goodWhere";$goodMeta=null;if($paging['paged']){$goodCount=db_row("SELECT COUNT(*) count FROM BBS_Community_Reports r $joins WHERE $goodWhere",$filterParams);$goodMeta=bbs_list_pagination((int)($goodCount['count']??0),$goodPage,$paging['pageSize']);$good=db_rows($goodSelect.' ORDER BY r.CreatedAt DESC,r.id DESC LIMIT '.(int)$goodMeta['pageSize'].' OFFSET '.(($goodMeta['page']-1)*$goodMeta['pageSize']),$filterParams);}else $good=db_rows($goodSelect.' ORDER BY r.CreatedAt 