        if($isAdmin){$risk=db_row("SELECT COUNT(*) risky,SUM(a.Status<>'Closed') openActions,SUM(a.Status<>'Closed' AND a.DueDate<CURDATE()) overdue FROM BBS_Community_Reports r LEFT JOIN BBS_Community_Actions a ON a.ReportID=r.id WHERE r.ReportType='Risky' AND $period",$periodParams);$data['summary']['risky']=(int)($risk['risky']??0);$data['summary']['openActions']=(int)($risk['openActions']??0);$data['summary']['overdue']=(int)($risk['overdue']??0);$riskWhere=["r.ReportType='Risky'",$base];$riskParams=$filterParams;if($actionStatus!==''){$riskWhere[]='a.Status=?';$riskParams[]=$actionStatus;}if($priority!==''){$riskWhere[]='a.Priority=?';$riskParams[]=$priority;}$riskSql=implode(' AND ',$riskWhere);$riskJoins="$joins JOIN employees reporter ON reporter.EmployeeID=r.ReporterEmployeeID LEFT JOIN BBS_Community_Actions a ON a.ReportID=r.id";$riskSelect="SELECT r.*,d.Name DepartmentName,u.name SafetyUnitName,reporter.EmployeeName ReporterName,observed.EmployeeName ObservedEmployeeName,a.id ActionID,a.ActionNo,a.Status ActionStatus,a.Priority,a.DueDate,a.RowVersion FROM BBS_Community_Reports r $riskJoins WHERE $riskSql";if($paging['paged']){$riskCount=db_row("SELECT COUNT(*) count FROM BBS_Community_Reports r $riskJoins WHERE $riskSql",$riskParams);$riskMeta=bbs_list_pagination((int)($riskCount['count']??0),$riskPage,$paging['pageSize']);$data['risky']=db_rows($riskSelect.' ORDER BY r.CreatedAt DESC,r.id DESC LIMIT '.(int)$riskMeta['pageSize'].' OFFSET '.(($riskMeta['page']-1)*$riskMeta['pageSize']),$riskParams);$data['pagination']['risky']=$riskMeta;}else $data['risky']=db_rows($riskSelect.' ORDER BY r.CreatedAt DESC,r.id DESC LIMIT 100',$riskParams);$printWhere='YEAR(l.PrintedAt)=?'.($month>=1&&$month<=12?' AND MONTH(l.PrintedAt)=?':'');$data['printing']=db_rows("SELECT t.TemplateName,d.Name DepartmentName,SUM(l.Copies) Copies,COUNT(*) PrintEvents FROM BBS_Department_Card_Print_Logs l JOIN BBS_Department_Card_Templates t ON t.id=l.TemplateID JOIN master_departments d ON d.id=t.DepartmentID WHERE $printWhere GROUP BY t.id,t.TemplateName,d.Name ORDER BY Copies DESC LIMIT 50",$periodParams);}json_response(['success'=>true,'data'=>$data]);
    }
    if($method==='POST'&&$path==='/bbs/community/reports'){
        if(!bbs_comm_enabled('community_reporting_enabled'))json_response(['success'=>false,'message'=>'Community reporting is disabled.'],409);$upload=bbs_comm_upload('evidence',bbs_comm_report_dir(),false);$departmentId=$isAdmin&&isset($_POST['departmentId'])?bbs_phase1_positive_int($_POST['departmentId']):(int)($employee['DepartmentID']??0);$type=bbs_community_report_type($_POST['reportType']??'');$description=mb_substr(trim((string)($_POST['description']??'')),0,8000);$observed=bbs_card_clean($_POST['observedEmployeeId']??'',20)?:null;$unit=bbs_phase1_positive_int($_POST['safetyUnitId']??null);$area=bbs_card_clean($_POST['areaText']??'',255)?:null;try{if(!$departmentId||!$type||$description==='')throw new InvalidArgumentException('Department, Good/Risky type, and description are required.');$pdo=db();$qr=bbs_comm_active_qr($departmentId,$pdo);if(!$qr){if($upload)@unlink($upload['target']);json_response(['success'=>false,'code'=>'DEPARTMENT_QR_REQUIRED','message'=>'This Department does not have an Active Community QR.'],409);}if($observed&&!db_row("SELECT e.EmployeeID FROM employees e JOIN master_departments d ON d.id=? AND LOWER(TRIM(d.Name))=LOWER(TRIM(e.Department)) WHERE e.EmployeeID=?",[$departmentId,$observed]))throw new InvalidArgumentException('Observed employee must belong to the report Department.');if($unit&&!db_row('SELECT id FROM master_safetyunits WHERE id=? AND department_id=?',[$unit,$departmentId]))throw new InvalidArgumentException('Safety Unit must belong to the report Department.');$handler=null;if($type==='Risky'){$handler=db_row("SELECT h.* FROM BBS_Community_Action_Handlers h JOIN employees owner ON owner.EmployeeID=h.OwnerEmployeeID AND LOWER(owner.Role)='admin' JOIN employees verifier ON verifier.EmployeeID=h.VerifierEmployeeID AND LOWER(verifier.Role)='admin' WHERE h.DepartmentID=? AND h.IsActive=1 LIMIT 1",[$departmentId]);if(!$handler){if($upload)@unlink($upload['target']);json_response(['success'=>false,'code'=>'COMMUNITY_HANDLER_REQUIRED','message'=>'Admin must configure an active Community Risk owner and verifier for this Department.'],409);}}$pdo->beginTransaction();$stmt=$pdo->prepare("INSERT INTO BBS_Community_Reports(ReportNo,DepartmentID,DepartmentQRID,ReporterEmployeeID,ObservedEmployeeID,SafetyUnitID,AreaText,ReportType,Description,Status) VALUES('',?,?,?,?,?,?,?,?,?)");$stmt->execute([$departmentId,$qr['id'],$user['id'],$observed,$unit,$area,$type,$description,$type==='Good'?'Published':'Action Open']);$reportId=(int)$pdo->lastInsertId();$reportNo='BBS-COM-'.str_pad((string)$reportId,8,'0',STR_PAD_LEFT);$pdo->prepare('UPDATE BBS_Community_Reports SET ReportNo=? WHERE id=?')->execute([$reportNo,$reportId]);if($upload)$pdo->prepare('INSERT INTO BBS_Community_Report_Files(ReportID,StoredName,OriginalName,MimeType,FileSize,UploadedBy) VALUES(?,?,?,?,?,?)')->execute([$reportId,$upload['stored'],$upload['name'],$upload['mime'],$upload['size'],$user['id']]);$actionId=null;if($type==='Risky'){$sla=db_row("SELECT SLADays FROM BBS_Action_SLA_Rules WHERE Priority='Medium' AND IsActive=1 LIMIT 1")?:[];$days=max(1,(int)($sla['SLADays']??7));$stmt=$pdo->prepare("INSERT INTO BBS_Community_Actions(ActionNo,ReportID,OwnerEmployeeID,VerifierEmployeeID,Priority,DueDate,Description,Status) VALUES('',?,?,?,'Medium',DATE_ADD(CURDATE(),INTERVAL ? DAY),?,'Open')");$stmt->execute([$reportId,$handler['OwnerEmployeeID'],$handler['VerifierEmployeeID'],$days,$description]);$actionId=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE BBS_Community_Actions SET ActionNo=? WHERE id=?')->execute(['BBS-COM-ACT-'.str_pad((string)$actionId,8,'0',STR_PAD_LEFT),$actionId]);$pdo->prepare("INSERT INTO BBS_Community_Action_History(ActionID,FromStatus,ToStatus,ActorEmployeeID,Note) VALUES(?,NULL,'Open',?,'Created automatically from Community Risky report.')")->execute([$actionId,$user['id']]);}$pdo->commit();bbs_phase1_audit($user,$type==='Good'?'BBS_COMMUNITY_GOOD_SUBMIT':'BBS_COMMUNITY_RISKY_SUBMIT','BBS_Community_Report',(string)$reportId,$reportNo);json_response(['success'=>true,'data'=>['id'=>$reportId,'reportNo'=>$reportNo,'reportType'=>$type,'actionId'=>$actionId]],201);}catch(InvalidArgumentException $e){if($upload)@unlink($upload['target']);json_response(['success'=>false,'message'=>$e->getMessage()],400);}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();if($upload)@unlink($upload['target']);throw$e;}}
    $evidence=route_params($path,'/bbs/community/reports/:id/evidence/:fileId');if($method==='GET'&&$evidence!==null){$report=db_row('SELECT ReportType FROM BBS_Community_Reports WHERE id=?',[bbs_phase1_positive_int($evidence['id'])]);if(!$report)json_response(['success'=>false,'message'=>'Community report was not found.'],404);if($report['ReportType']==='Risky'&&!$isAdmin)json_response(['success'=>false,'message'=>'Risky report evidence is Admin-only.'],403);$fileRow=db_row('SELECT * FROM BBS_Community_Report_Files WHERE id=? AND ReportID=?',[bbs_phase1_positive_int($evidence['fileId']),bbs_phase1_positive_int($evidence['id'])]);if(!$fileRow)json_response(['success'=>false,'message'=>'Evidence was not found.'],404);$file=bbs_comm_report_dir().'/'.basename((string)$fileRow['StoredName']);if(!is_file($file))json_response(['success'=>false,'message'=>'Evidence file is unavailable.'],404);header('Content-Type: '.$fileRow['MimeType']);header("Content-Disposition: inline; filename*=UTF-8''".rawurlencode((string)$fileRow['OriginalName']));readfile($file);exit;}

    if(strpos($path,'/bbs/admin/')!==0)return false;$admin=require_admin();
    $riskDetail=route_params($path,'/bbs/admin/community-reports/:id');if($method==='GET'&&$riskDetail!==null){$id=bbs_phase1_positive_int($riskDetail['id']);if(!$id)json_response(['success'=>false,'message'=>'Valid Community report ID is required.'],400);$report=db_row("SELECT r.id,r.ReportNo,r.DepartmentID,d.Name DepartmentName,r.ReporterEmployeeID,reporter.EmployeeName ReporterName,r.ObservedEmployeeID,observed.EmployeeName ObservedEmployeeName,r.SafetyUnitID,u.name SafetyUnitName,r.AreaText,r.ReportType,r.Description,r.Status,r.CreatedAt FROM BBS_Community_Reports r JOIN master_departments d ON d.id=r.DepartmentID JOIN employees reporter ON reporter.EmployeeID=r.ReporterEmployeeID LEFT JOIN employees observed ON observed.EmployeeID=r.ObservedEmployeeID LEFT JOIN master_safetyunits u ON u.id=r.SafetyUnitID WHERE r.id=? AND r.ReportType='Risky' LIMIT 1",[$id]);if(!$report)json_response(['success'=>false,'message'=>'Community Risk report was not found.'],404);$files=db_rows('SELECT id,ReportID,OriginalName,MimeType,FileSize,UploadedBy,CreatedAt FROM BBS_Community_Report_Files WHERE ReportID=? ORDER BY CreatedAt,id',[$id]);$action=db_row('SELECT a.*,owner.EmployeeName OwnerName,verifier.EmployeeName VerifierName,closed.EmployeeName ClosedByName FROM BBS_Community_Actions a JOIN employees owner ON owner.EmployeeID=a.OwnerEmployeeID JOIN employees verifier ON verifier.EmployeeID=a.VerifierEmployeeID LEFT JOIN employees closed ON closed.EmployeeID=a.ClosedBy WHERE a.ReportID=? LIMIT 1',[$id]);if($action)$action['history']=db_rows('SELECT h.id,h.ActionID,h.FromStatus,h.ToStatus,h.ActorEmployeeID,actor.EmployeeName ActorName,h.Note,h.CreatedAt FROM BBS_Community_Action_History h LEFT JOIN employees actor ON actor.EmployeeID=h.ActorEmployeeID WHERE h.ActionID=? ORDER BY h.CreatedAt,h.id',[(int)$action['id']]);json_response(['success'=>true,'data'=>['report'=>$report,'files'=>$files,'action'=>$action?:null]]);}
    if($method==='GET'&&$path==='/bbs/admin/department-cards'){$templates=db_rows("SELECT t.*,d.Name DepartmentName FROM BBS_Department_Card_Templates t JOIN master_departments d ON d.id=t.DepartmentID ORDER BY d.Name,FIELD(t.Status,'Active','Draft','Archived'),t.DisplayOrder,t.id");$qr=db_rows("SELECT q.*,d.Name DepartmentName FROM BBS_Department_QR_Cards q JOIN master_departments d ON d.id=q.DepartmentID ORDER BY q.Status='Active' DESC,d.Name,q.Generation DESC");$handlers=db_rows('SELECT h.*,d.Name DepartmentName,o.EmployeeName OwnerName,v.EmployeeName VerifierName FROM BBS_Community_Action_Handlers h JOIN master_departments d ON d.id=h.DepartmentID JOIN employees o ON o.EmployeeID=h.OwnerEmployeeID JOIN employees v ON v.EmployeeID=h.VerifierEmployeeID ORDER BY d.Name');$admins=db_rows("SELECT EmployeeID,EmployeeName,Department FROM employees WHERE LOWER(Role)='admin' ORDER BY EmployeeName");$departments=db_rows('SELECT id,Name FROM master_departments ORDER BY Name');json_response(['success'=>true,'data'=>['templates'=>$templates,'qrCards'=>$qr,'handlers'=>$handlers,'admins'=>$admins,'departments'=>$departments]]);}
